// Exercises real controller methods against lightweight test doubles, NOT Unity Play Mode.
using System;using System.Reflection;using System.Linq;using UnityEngine;using IoTDigitalTwin;
class ControllerLogicTests {
 static int assertions;
 static void Check(bool ok,string label){assertions++;if(!ok)throw new Exception(label);}
 static void Near(float a,float b,string label){Check(Math.Abs(a-b)<.00002f,label+" "+a+" != "+b);}
 static void Call(object o,string method){o.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,null);}
 static T Make<T>()where T:Component{return new GameObject(typeof(T).Name).AddComponent<T>();}
 static Transform Part(Transform parent,Vector3 pos){var p=new GameObject("Part").transform;p.SetParent(parent,false);p.localPosition=pos;return p;}
 static DynamicReadout Text(){var t=Make<DynamicReadout>();t.gameObject.AddComponent<MeshFilter>();t.gameObject.AddComponent<MeshRenderer>();t.glyphs=Enumerable.Range(32,96).Select(i=>new FontGlyph{code=i,width=40,height=60,advance=44}).ToArray();return t;}
 static void Step(object o,int n=100){for(int i=0;i<n;i++)Call(o,"Update");}
 static void Main(){
  Time.deltaTime=.02f;
  var d=Make<RotaryDimmer>();d.knob=Part(d.transform,new Vector3(0,0,.01f));Call(d,"Awake");var pivot=d.knob.position;int events=0;d.StateChanged+=x=>events++;d.SetBrightness(2);d.SetPower(false);Step(d);Near(d.Brightness,1,"dimmer clamp");Check(!d.Power&&events==2,"dimmer events");Near((d.knob.position-pivot).magnitude,0,"dimmer shaft pivot");d.ControlDown("Knob",Vector2.zero);Step(d,1);Check(d.knob.localPosition.z<.01f,"knob press");Step(d);Near(d.knob.localPosition.z,.01f,"knob press recovery");d.ControlUp("Knob",true,Vector2.zero);Check(d.Power,"knob click toggles power");d.ControlDrag("Knob",Vector2.zero,new Vector2(-100,0));Near(d.Brightness,.6f,"knob drag");
  var lcd=Make<TemperatureLCD>();lcd.temperatureText=Text();lcd.humidityText=Text();lcd.pairingText=Text();lcd.buttons=Enumerable.Range(0,3).Select(i=>new PressPart{part=Part(lcd.transform,Vector3.zero)}).ToArray();Call(lcd,"Awake");lcd.SetTemperature(29);lcd.SetHumidity(67);Check(lcd.temperatureText.Value=="29.0°C"&&lcd.humidityText.Value=="67%","live LCD readings");lcd.Control("Plus",Vector2.zero);Near(lcd.Temperature,29.5f,"LCD plus");lcd.Control("Mode",Vector2.zero);lcd.Control("Minus",Vector2.zero);Near(lcd.Humidity,66,"LCD humidity mode");Check(lcd.buttons[1].amount==1,"button press");lcd.SetPairing(true);Check(lcd.pairingText.Value=="PAIR","pairing label");lcd.SetPairing(false);Check(lcd.pairingText.Value=="","pairing clear");lcd.SetHumidity(200);Near(lcd.Humidity,100,"humidity clamp");
  var t=Make<TemperatureController>();t.measuredText=Text();t.targetText=Text();t.stateText=Text();t.modeText=Text();Call(t,"Awake");t.SetTemperature(24);t.SetTargetTemperature(30);Check(t.measuredText.Value=="24.0°C"&&t.targetText.Value=="SET 30.0","thermostat live display");t.Control("Schedule",Vector2.zero);Check(t.schedule&&t.modeText.Value.Contains("SCHEDULE"),"schedule key");t.Control("Mode",Vector2.zero);Check(t.mode==ThermostatMode.Heat,"mode key");t.Control("Down",Vector2.zero);Near(t.TargetTemperature,29.5f,"down key");t.Control("Up",Vector2.zero);Near(t.TargetTemperature,30,"up key");t.Control("Power",Vector2.zero);Check(!t.Power&&t.stateText.Value=="OFF","power key");t.SetTargetTemperature(90);Near(t.TargetTemperature,35,"target clamp");
  var cam=Make<SecurityCameraDevice>();cam.head=Part(cam.transform,new Vector3(0,.015f,.05f));cam.flood.light=Make<Light>();Call(cam,"Awake");var headPivot=cam.head.position;cam.SetTilt(100);cam.SetYaw(-100);cam.SetFloodlight(true);Step(cam);Near(cam.Tilt,35,"tilt limit");Near(cam.Yaw,-30,"yaw limit");Near((cam.head.position-headPivot).magnitude,0,"camera hinge fixed");Check(cam.flood.light.enabled&&cam.flood.light.intensity>0,"camera floodlight");cam.SetPower(false);Step(cam,1);Check(!cam.flood.light.enabled,"camera power disables floodlight");cam.ControlUp("Head",true,Vector2.zero);Check(cam.Power,"camera head click");
  var b=Make<RollerBlindDevice>();b.bottomRail=Part(b.transform,new Vector3(0,-.484f,.061f));b.roller=Part(b.transform,new Vector3(0,-.03f,.035f));b.clutch=Part(b.transform,new Vector3(-.620f,-.03f,.035f));b.cloth=Make<SkinnedMeshRenderer>();Call(b,"Awake");b.percentPerSecond=100;b.Open();Step(b,50);Near(b.OpenPercent,100,"blind open");Near(b.bottomRail.localPosition.y,-.05875f,"blind raised rail");Near(b.cloth.GetBlendShapeWeight(0),100,"blind raised morph");b.Close();Step(b,20);b.Stop();var stopped=b.OpenPercent;Step(b);Near(b.OpenPercent,stopped,"blind Stop holds");b.Close();Step(b,50);Near(b.OpenPercent,0,"blind closed");Near(b.bottomRail.localPosition.y,-.484f,"blind closed rail");b.ControlDrag("Position",new Vector2(.35f,.5f),Vector2.zero);Near(b.TargetOpenPercent,35,"rail drag");
  var a=Make<AqaraChainController>();a.sprocket=Part(a.transform,Vector3.zero);a.cover=Part(a.transform,Vector3.zero);a.raiseButton.part=Part(a.transform,Vector3.zero);a.lowerButton.part=Part(a.transform,Vector3.zero);Call(a,"Awake");a.Raise();Step(a,20);Check(a.OpenPercent>0,"Aqara independent raise");a.Stop();var held=a.OpenPercent;Step(a);Near(a.OpenPercent,held,"Aqara Stop");a.SetCoverOpen(true);Step(a);Near(a.cover.localPosition.y,.018f,"cover slide");a.ConnectBlind(b);a.SetOpenPercent(70);Near(b.TargetOpenPercent,70,"optional blind link");a.ConnectBlind(null);Check(a.LinkedBlind==null,"Aqara independent disconnect");
  var dots=Make<DynamicDotDisplay>();dots.filter=dots.gameObject.AddComponent<MeshFilter>();dots.filter.sharedMesh=new Mesh{vertices=new Vector3[36*8]};Call(dots,"Awake");var si=Make<SiemensBACnetDevice>();si.display=dots;si.SetDisplayValue(42);Check(dots.filter.sharedMesh.colors.Count(c=>c.a>.5f)>0,"dynamic LED colours");var c42=(Color[])dots.filter.sharedMesh.colors.Clone();si.SetDisplayValue(11);Check(!c42.Select(c=>c.a).SequenceEqual(dots.filter.sharedMesh.colors.Select(c=>c.a)),"LED pattern changes");si.SetStatus(false);Check(!si.Status,"Siemens status");si.SetDisplayValue(150);Near(si.DisplayValue,99,"LED clamp");
  var sp=Make<NestSpeakerDevice>();sp.muteSwitch=Part(sp.transform,Vector3.zero);sp.lights=Enumerable.Range(0,4).Select(i=>new Indicator()).ToArray();Call(sp,"Awake");sp.SetVolume(2);Near(sp.Volume,1,"volume clamp");sp.ControlDown("Mute",Vector2.zero);Check(sp.Muted,"mute click");Step(sp);Near(sp.muteSwitch.localPosition.y,.003f,"mute slide");sp.ControlUp("Volume",true,Vector2.zero);Check(!sp.Active,"speaker active click");sp.ControlDrag("Volume",Vector2.zero,new Vector2(-100,0));Near(sp.Volume,.7f,"volume drag");
  var p=Make<DALILightingPanel>();p.percentText=Text();p.kelvinText=Text();p.brightnessThumb=Part(p.transform,Vector3.zero);p.tempThumb=Part(p.transform,Vector3.zero);p.colorMarker=Part(p.transform,Vector3.zero);p.sceneMarker=Part(p.transform,Vector3.zero);p.scenePositions=new[]{Vector3.zero,Vector3.up,Vector3.right};p.brightnessTop=Vector3.up;p.tempCool=Vector3.up;p.colorTopRight=Vector3.one;Call(p,"Awake");p.SetBrightness(.65f);Check(p.percentText.Value=="65%","DALI live percentage");Near(p.brightnessThumb.localPosition.y,.65f,"DALI brightness marker");p.SetColor(Color.red);Check(p.SelectedColor.r==1&&p.SelectedColor.g==0&&!p.useTemperature,"DALI RGB state");p.SetColorTemperature(9000);Near(p.ColorTemperature,6500,"DALI Kelvin clamp");Check(p.kelvinText.Value=="6500K","DALI Kelvin display");p.SelectScene(2);Near(p.Brightness,.15f,"scene 2");Near((p.sceneMarker.localPosition-Vector3.right).magnitude,0,"scene marker");foreach(var action in new[]{"On","Off","Brightness","Colour_Temperature","Colour_Field","Scene_Task","Scene_Presentation_1","Scene_Presentation_2"})p.Control(action,new Vector2(.6f,.7f));Check(p.sceneIndex==2,"all eight touchscreen dispatch paths");
  var chain=Make<BeadChainMotion>();chain.frame=chain.transform;chain.filter=chain.gameObject.AddComponent<MeshFilter>();chain.top=.257f;chain.bottom=.071f;chain.radius=.016f;chain.depth=.013f;var centre=new Vector3(-.016f,.257f,.013f);chain.filter.sharedMesh=new Mesh{vertices=new[]{centre+Vector3.up*.001f,centre-Vector3.up*.001f}};chain.islands=new[]{new ChainIsland{indices=new[]{0,1},centre=centre,arcDistance=0}};Call(chain,"Awake");var separation=(chain.filter.sharedMesh.vertices[0]-chain.filter.sharedMesh.vertices[1]).magnitude;chain.Advance(.02f);Near(chain.filter.sharedMesh.vertices[0].y,.238f,"chain movement");Near((chain.filter.sharedMesh.vertices[0]-chain.filter.sharedMesh.vertices[1]).magnitude,separation,"bead geometry preserved");
  bool reject=false;try{p.SetBrightness(float.NaN);}catch(ArgumentOutOfRangeException){reject=true;}Check(reject,"NaN rejected through API");
  Console.WriteLine("PASS: "+assertions+" controller logic assertions with test doubles. NOT actual Unity Play Mode, rendering, physics or FBX import tests.");
 }
}
